arguments.newString:
/**
 * Maximum length of a log message before it is truncated. This prevents the output channel from becoming unresponsive
 * if the runner produces a large amount of output.
 */
const MAX_LOG_LENGTH = 10_000;

/**
 * Truncate a message if it exceeds the maximum allowed length to keep the output channel responsive.
 *
 * @param value Message to truncate.
 * @return The truncated message, or the original message if it is short enough.
 */
const truncate = function (value: string): string {
    if (value.length <= MAX_LOG_LENGTH) {
        return value;
    }
    return `${value.slice(0, MAX_LOG_LENGTH)}... [truncated]`;
};

/**
 * Initialize the logging system once for the extension.
 */
export const initializeLog = function () {
    logOutputChannel = vscode.window.createOutputChannel('Safe-DS', { log: true });
    logOutputChannel.show();
};

