        // Type parameters may be used in the constructor of a class (or any class header context)
        if (isSdsClass(containingClassMember)) {
            return;
        }

        // Type parameters must not be used in static class members
        if (isStatic(containingClassMember)) {
            accept('error', 'This type parameter of a containing class cannot be used here.', {
                node: reference,
                code: CODE_TYPE_PARAMETER_USAGE,
            });
        }
    });
};
```

