const getTypePosition = (
    nodeMapper: SafeDsNodeMapper,
    reference: SdsType,
    declarationWithTypeParameter: SdsDeclaration,
): TypePosition => {
    let position: TypePosition = 'covariant';
    let current: AstNode = reference;

    while (current !== declarationWithTypeParameter) {
        const parent = current.$container;
