            // The right operand of a 'sub' constraint is in a covariant position, the right operand of a 'super'
            // constraint is in a contravariant position
            if (parent.operator === 'super') {
                position = flip(position);
            }
        }

        current = parent;
    }

    return position;
};

/**
 * Flips the given position.
 *
 * @param position The position.
 * @returns The flipped position.
 */
const flip = (position: TypePosition): TypePosition => {
    if (position === 'covariant') {
        return 'contravariant';
    } else if (position === 'contravariant') {
        return 'covariant';
    } else {
        return 'invariant';
